import{_ as e,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Страницы - October CMS - 3.x","titleTemplate":false,"description":"Определите URL для каждой страницы вашего сайта.","frontmatter":{"subtitle":"Определите URL для каждой страницы вашего сайта."},"headers":[{"level":2,"title":"Конфигурация страницы","slug":"конфигурация-страницы","link":"#конфигурация-страницы","children":[{"level":3,"title":"Синтаксис URL","slug":"синтаксис-url","link":"#синтаксис-url","children":[]}]},{"level":2,"title":"Динамические страницы","slug":"динамические-страницы","link":"#динамические-страницы","children":[{"level":3,"title":"Жизненный цикл выполнения страницы","slug":"жизненныи-цикл-выполнения-страницы","link":"#жизненныи-цикл-выполнения-страницы","children":[]},{"level":3,"title":"Отправка пользовательского ответа","slug":"отправка-пользовательского-ответа","link":"#отправка-пользовательского-ответа","children":[]},{"level":3,"title":"Обработка форм","slug":"обработка-форм","link":"#обработка-форм","children":[]}]},{"level":2,"title":"Страница 404","slug":"страница-404","link":"#страница-404","children":[]},{"level":2,"title":"Страница ошибки","slug":"страница-ошибки","link":"#страница-ошибки","children":[]},{"level":2,"title":"Установка заголовка страницы","slug":"установка-заголовка-страницы","link":"#установка-заголовка-страницы","children":[{"level":3,"title":"Использование свойств страницы","slug":"использование-своиств-страницы","link":"#использование-своиств-страницы","children":[]},{"level":3,"title":"Использование переменных-заполнителей","slug":"использование-переменных-заполнителеи","link":"#использование-переменных-заполнителеи","children":[]}]},{"level":2,"title":"Программное подключение ресурсов страницы","slug":"программное-подключение-ресурсов-страницы","link":"#программное-подключение-ресурсов-страницы","children":[]}],"relativePath":"3.x/ru/cms/themes/pages.md","filePath":"3.x/ru/cms/themes/pages.md"}'),u={name:"3.x/ru/cms/themes/pages.md"};function r(k,n,d,g,h,v){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"Страницы",-1)),s(p),n[1]||(n[1]=i(`<p>Каждый сайт содержит хотя бы одну страницу, и в October CMS страница представлена шаблоном страницы. Файлы шаблонов страниц располагаются в каталоге <strong>pages</strong> вашей темы. Имена файлов страниц не влияют на маршрутизацию, но рекомендуется называть страницы в соответствии с их назначением. Файлы должны иметь расширение <strong>htm</strong>.</p><p>Секции конфигурации и Twig-шаблона обязательны для страниц, а секция PHP является необязательной. Ниже вы можете увидеть простейший пример главной страницы.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="конфигурация-страницы"><a href="#конфигурация-страницы" class="header-anchor">#</a> Конфигурация страницы</h2><p>Конфигурация страницы определяется в секции конфигурации файла шаблона страницы. Конфигурация страницы задаёт параметры, необходимые для маршрутизации и рендеринга страницы и её <a href="./components.html">компонентов</a>, которые описаны в отдельной статье. Для страниц поддерживаются следующие параметры конфигурации:</p><div class="table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>URL страницы, обязательный. Синтаксис URL описан ниже.</td></tr><tr><td><strong>title</strong></td><td>заголовок страницы, обязательный.</td></tr><tr><td><strong>layout</strong></td><td><a href="./layouts.html">макет</a> страницы, необязательный. Если указан, должен содержать имя файла макета без расширения, например: <code>default</code>.</td></tr><tr><td><strong>description</strong></td><td>описание страницы для интерфейса администрирования, необязательный.</td></tr><tr><td><strong>hidden</strong></td><td>скрытые страницы доступны только авторизованным пользователям панели администрирования, необязательный.</td></tr></tbody></table></div><h3 id="синтаксис-url"><a href="#синтаксис-url" class="header-anchor">#</a> Синтаксис URL</h3><p>URL страницы определяется параметром конфигурации <strong>url</strong>. URL должен начинаться с символа прямой косой черты и может содержать параметры. URL без параметров являются фиксированными и строгими. В следующем примере URL страницы — <code>/blog</code>.</p><div class="custom-block tip"><p>URL страницы по умолчанию нечувствителен к регистру.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div></div><p>URL с параметрами являются более гибкими. Страница с шаблоном URL, определённым в следующем примере, будет отображаться для любого адреса вида <code>/blog/post/something</code>. Параметры URL могут быть доступны компонентам October или из секции PHP-кода страницы.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><p>Вот как можно получить доступ к параметру URL из секции PHP страницы (подробнее см. раздел «Динамические страницы»).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code></code></pre></div></div><p>Имена параметров должны быть совместимы с именами переменных PHP. Чтобы сделать параметр необязательным, добавьте знак вопроса после его имени:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id?</span>&quot;</span>
</code></pre></div><p>Параметры в середине URL не могут быть необязательными. В следующем примере параметр <code>:post_id</code> помечен как необязательный, но обрабатывается как обязательный.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:post_id?/comments</span>&quot;</span>
</code></pre></div><p>Необязательные параметры могут иметь значения по умолчанию, которые используются в качестве запасных значений, если реальное значение параметра отсутствует в URL. Значения по умолчанию не могут содержать звёздочки, символы вертикальной черты или вопросительные знаки. Значение по умолчанию указывается после <strong>вопросительного знака</strong>. В следующем примере значение параметра <code>category_id</code> будет равно <code>10</code> для URL <code>/blog/category</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/category/:category_id?10</span>&quot;</span>
</code></pre></div><p>Вы также можете использовать регулярные выражения для валидации параметров. Чтобы добавить выражение валидации, поставьте символ вертикальной черты после имени параметра или вопросительного знака и укажите выражение. Символ прямой косой черты не допускается в этих выражениях. Примеры:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$/comments&quot; ; this will match /blog/10/comments</span>

<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$&quot; ; this will match /blog/3</span>

<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_name?|^[a-z0-9\\-]+$&quot; ; this will match /blog/my-blog-post</span>
</code></pre></div><p>Можно использовать специальный <em>подстановочный</em> параметр, поставив <strong>звёздочку</strong> после параметра. В отличие от обычных параметров, подстановочные параметры могут совпадать с одним или несколькими сегментами URL. URL может содержать только один подстановочный параметр, он не может использовать регулярные выражения и за ним не может следовать необязательный параметр.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:category*/:slug</span>&quot;</span>
</code></pre></div><p>Сами подстановочные параметры могут быть сделаны необязательными, поставив символ <code>?</code> перед звёздочкой.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:slug?*</span>&quot;</span>
</code></pre></div><p>Например, URL вида <code>/color/:color/make/:make*/edit</code> будет совпадать с <code>/color/brown/make/volkswagen/beetle/retro/edit</code> и извлечёт следующие значения параметров:</p><ul><li>color: <code>brown</code></li><li>make: <code>volkswagen/beetle/retro</code></li></ul><div class="custom-block tip"><p>Подкаталоги не влияют на URL страниц — URL определяется только параметром <strong>url</strong>.</p></div><h2 id="динамические-страницы"><a href="#динамические-страницы" class="header-anchor">#</a> Динамические страницы</h2><p>Внутри секции Twig шаблона страницы вы можете использовать любые <a href="./../../markup/templating.html">функции, фильтры и теги, предоставляемые October CMS</a>. Любая динамическая страница требует <strong>переменных</strong>, которые могут быть подготовлены в секции PHP страницы или макета, либо <a href="./components.html">компонентами</a>. В этой статье мы описываем, как подготавливать переменные в секции PHP.</p><h3 id="жизненныи-цикл-выполнения-страницы"><a href="#жизненныи-цикл-выполнения-страницы" class="header-anchor">#</a> Жизненный цикл выполнения страницы</h3><p>Существуют специальные функции, которые можно определить в секции PHP страниц и макетов: <code>onInit</code>, <code>onStart</code> и <code>onEnd</code>. Функция <code>onInit</code> выполняется, когда все компоненты инициализированы и до обработки AJAX-запросов. Функция <code>onStart</code> выполняется в начале выполнения страницы. Функция <code>onEnd</code> выполняется перед рендерингом страницы и после выполнения <a href="./components.html">компонентов</a> страницы. В функциях <code>onStart</code> и <code>onEnd</code> вы можете передавать переменные в окружение Twig. Используйте <code>$this</code> с нотацией массива для передачи переменных на страницу.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hello&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Следующий пример более сложный. Он показывает, как загрузить коллекцию записей блога из базы данных и отобразить их на странице (плагин <code>Acme\\Blog</code> — вымышленный).</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Post</span><span class="token punctuation">;</span>

<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>Latest posts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content <span class="token delimiter punctuation">}}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Переменные по умолчанию и расширения Twig, предоставляемые October CMS, описаны в <a href="./../../markup/templating.html">руководстве по разметке</a>. Последовательность выполнения обработчиков описана в разделе <a href="./layouts.html">Динамические макеты</a>.</p><h3 id="отправка-пользовательского-ответа"><a href="#отправка-пользовательского-ответа" class="header-anchor">#</a> Отправка пользовательского ответа</h3><p>Все методы, определённые в жизненном цикле выполнения, могут прервать процесс и вернуть ответ — просто верните ответ из функции жизненного цикла. Пример ниже не загружает содержимое страницы, а вместо этого возвращает строку <em>Hello world!</em> в браузер:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Более полезным примером может быть перенаправление с использованием фасада <code>Redirect</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="обработка-форм"><a href="#обработка-форм" class="header-anchor">#</a> Обработка форм</h3><p>Вы можете обрабатывать стандартные формы с помощью методов-обработчиков, определённых в секции PHP страницы или макета (обработка AJAX-запросов описана в статье <a href="./../ajax/introduction.html">AJAX Framework</a>). Используйте <a href="./../../markup/function/form.html">Twig-функцию</a> <code>form_open()</code> для определения формы, которая ссылается на обработчик событий.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>Please enter a string<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value<span class="token punctuation">&quot;</span></span><span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Last submitted value: {{ lastValue }}<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Функция <code>onHandleForm</code> может быть определена в секции PHP страницы или макета.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onHandleForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;lastValue&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Обработчик загружает значение с помощью функции <code>post</code> и инициализирует атрибут-переменную <code>lastValue</code> страницы, которая отображается под формой в первом примере.</p><div class="custom-block tip"><p>Если обработчик с одинаковым именем определён в макете страницы, на самой странице и в <a href="./components.html">компоненте страницы</a>, October CMS выполнит обработчик страницы. Если обработчик определён в компоненте и в макете, будет выполнен обработчик макета. Приоритет обработчиков: страница, макет, компонент.</p></div><p>Если вы хотите обратиться к обработчику, определённому в конкретном компоненте, используйте имя или псевдоним компонента в ссылке на обработчик:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myComponent::onHandleForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="страница-404"><a href="#страница-404" class="header-anchor">#</a> Страница 404</h2><p>Если тема содержит страницу с URL <code>/404</code>, она отображается, когда система не может найти запрошенную страницу.</p><h2 id="страница-ошибки"><a href="#страница-ошибки" class="header-anchor">#</a> Страница ошибки</h2><p>По умолчанию любые ошибки отображаются на детальной странице ошибки, содержащей содержимое файла, номер строки и стек вызовов, где произошла ошибка. Вы можете отображать пользовательскую страницу ошибки, установив значение конфигурации <code>debug</code> в <strong>false</strong> в скрипте <code>config/app.php</code> и создав страницу с URL <code>/error</code>.</p><h2 id="установка-заголовка-страницы"><a href="#установка-заголовка-страницы" class="header-anchor">#</a> Установка заголовка страницы</h2><p>Установка заголовка страницы может быть выполнена в PHP с использованием объекта страницы или в Twig с использованием <a href="./../../markup/tag/placeholder.html">тега placeholder</a>.</p><h3 id="использование-своиств-страницы"><a href="#использование-своиств-страницы" class="header-anchor">#</a> Использование свойств страницы</h3><p>Свойства страницы доступны в секции PHP-кода или <a href="./components.html">компонентах</a> через обращение к <code>$this-&gt;page</code>. Следующий пример устанавливает новое значение атрибута <code>meta_title</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token operator">-&gt;</span><span class="token property">meta_title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;A different page title&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Переменная <code>{{ this.page }}</code> доступна в Twig через переменную <code>this.page</code>. Например, для возврата атрибута <code>meta_title</code> внутри макета.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>meta_title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Более подробную информацию о <code>this.page</code> можно найти в <a href="./../../markup/property/this-page.html">руководстве по разметке</a>.</p></div><h3 id="использование-переменных-заполнителеи"><a href="#использование-переменных-заполнителеи" class="header-anchor">#</a> Использование переменных-заполнителей</h3><p>Тег <code>{% put %}</code> позволяет сохранить значение в переменной-заполнителе. Следующий пример устанавливает переменную <code>pageTitle</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> pageTitle <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>Yet another page title<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Twig-функция <code>placeholder()</code> используется для доступа к переменной внутри макета.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>pageTitle<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Значение по умолчанию (второй аргумент) может быть указано в качестве запасного.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> placeholder<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>pageTitle<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>meta_title<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Более подробную информацию о теге placeholder можно найти в <a href="./../../markup/tag/placeholder.html">статье о теге placeholder</a>.</p></div><h2 id="программное-подключение-ресурсов-страницы"><a href="#программное-подключение-ресурсов-страницы" class="header-anchor">#</a> Программное подключение ресурсов страницы</h2><p>При необходимости вы можете подключать ресурсы (файлы CSS и JavaScript) к страницам с помощью методов контроллера <code>addCss</code> и <code>addJs</code>. Это можно сделать в функции <code>onStart</code>, определённой в секции PHP страницы или <a href="./layouts.html">шаблона макета</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Если путь, указанный в аргументе методов <code>addCss</code> и <code>addJs</code>, начинается с косой черты (/), он будет относительным к корню сайта. Если путь к ресурсу не начинается с косой черты, он является относительным к теме.</p><p>Подключаемые ресурсы можно объединять, передавая их в виде массива:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/css/hello.css&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/css/goodbye.css&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/js/nav.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Ресурсы LESS и SCSS могут быть подключены и скомпилированы с помощью комбайнера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addCss</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/less/base.less&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Второй аргумент методов <code>addCss</code> и <code>addJs</code> позволяет указать дополнительные атрибуты для подключаемых ресурсов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;assets/js/app.js&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;assets/js/nav.js&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Для вывода подключённых ресурсов на страницах или <a href="./layouts.html">макетах</a> используйте теги <code>{% styles %}</code> и <code>{% scripts %}</code>. Пример:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">styles</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    ...
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">scripts</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Более подробную информацию о тегах <code>{% styles %}</code> и <code>{% scripts %}</code> можно найти в <a href="./../../markup/tag/placeholder.html">руководстве по разметке</a>.</p></div>`,83))])}const w=e(u,[["render",r]]);export{f as __pageData,w as default};
